insert into public.quiz_bank (title, description, group_id, quiz_type, difficulty, category, questions, scheduled_date, status, verified_at, verification_notes)
values
  ('ILLIT: Magnetic Debut Quiz', 'Ten easy questions on ILLIT''s debut: R U Next?, Belift Lab, the five members, Magnetic and their first EPs.', 68, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which TV channel aired R U Next?, the 2023 survival show that formed ILLIT?","options":["Mnet","JTBC","SBS","KBS2"],"correct":1,"fun_fact":"The show ran for ten episodes from June to September 2023, with 22 contestants competing for a place in the group.","source":"https://en.wikipedia.org/wiki/Illit"},{"question":"Which HYBE label manages ILLIT?","options":["Source Music","ADOR","Belift Lab","Pledis Entertainment"],"correct":2,"fun_fact":"Belift Lab also manages the boy group ENHYPEN, which it formed through the 2020 survival show I-Land.","source":"https://en.wikipedia.org/wiki/Belift_Lab"},{"question":"Which HYBE chairman took part as a producer on ILLIT''s debut EP?","options":["Park Jin-young","Lee Soo-man","Yang Hyun-suk","Bang Si-hyuk"],"correct":3,"fun_fact":"The EP came out on March 25, 2024, the date of the group''s official debut.","source":"https://en.wikipedia.org/wiki/Illit"},{"question":"What is the title of ILLIT''s debut EP?","options":["Super Real Me","I''ll Like You","Bomb","Not Cute Anymore"],"correct":0,"fun_fact":"Super Real Me sold more than 380,000 physical copies worldwide in its first week and passed 500,000 by the end of April 2024.","source":"https://en.wikipedia.org/wiki/Super_Real_Me"},{"question":"Which Super Real Me track got its own music video on April 17, 2024?","options":["Cherish (My Love)","Lucky Girl Syndrome","Do the Dance","Almond Chocolate"],"correct":1,"fun_fact":"The debut EP has four tracks, in this order: My World, Magnetic, Midnight Fiction and Lucky Girl Syndrome.","source":"https://en.wikipedia.org/wiki/Super_Real_Me"},{"question":"Magnetic was the first K-pop group debut song on the Billboard Hot 100. Where did it enter?","options":["No. 1","No. 45","No. 91","No. 100"],"correct":2,"fun_fact":"Billboard named ILLIT its first-ever K-Pop Rookie of the Month, for June 2024.","source":"https://www.billboard.com/music/pop/illit-kpop-rookie-of-the-month-june-2024-magnetic-1235718156/"},{"question":"Where did ILLIT make their first public appearance as a group, before their debut?","options":["Paris Fashion Week","Coachella","MAMA Awards","KCON Los Angeles"],"correct":0,"fun_fact":"They attended the Acne Studios show there, then became the faces of the brand''s SS24 global campaign in March 2024.","source":"https://en.wikipedia.org/wiki/Illit"},{"question":"Which of these singers is a member of ILLIT?","options":["Hanni","Wonyoung","Karina","Iroha"],"correct":3,"fun_fact":"Belift Lab''s official profile lists five members: Yunah, Minju, Moka, Wonhee and Iroha.","source":"https://beliftlab.com/artist/profile/Illit"},{"question":"According to Belift Lab, ILLIT''s name joins the phrase I will with which pronoun?","options":["It","Us","You","Me"],"correct":0,"fun_fact":"Belift Lab says I will stands for an independent, adventurous spirit, while It symbolizes something unique.","source":"https://beliftlab.com/artist/profile/Illit"},{"question":"Which song led the second ILLIT EP, I''ll Like You, in October 2024?","options":["Magnetic","Lucky Girl Syndrome","Do the Dance","Cherish (My Love)"],"correct":3,"fun_fact":"An English version of Tick-Tack from the same EP, titled Baby It''s Both, featured American singer Ava Max.","source":"https://en.wikipedia.org/wiki/I%27ll_Like_You"}]'::jsonb, '2026-10-20'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Illit ; https://beliftlab.com/artist/profile/Illit ; https://en.wikipedia.org/wiki/Belift_Lab ; https://en.wikipedia.org/wiki/Super_Real_Me ; https://en.wikipedia.org/wiki/Magnetic_(Illit_song) ; https://www.billboard.com/music/pop/illit-kpop-rookie-of-the-month-june-2024-magnetic-1235718156/ ; https://www.billboard.com/music/chart-beat/illit-hot-100-debut-magnetic-1235657757/ ; https://koreajoongangdaily.joins.com/news/2024-02-13/entertainment/kpop/ILLIT-girl-group-from-R-U-Next-to-debut-under-HYBE-in-March/1979559 ; https://www.nme.com/news/music/hybe-latest-girl-group-illit-acne-studios-global-campaign-3601685 ; https://en.wikipedia.org/wiki/I%27ll_Like_You ; https://www.wikidata.org/wiki/Q122179261. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop at Big Sporting Events', 'From the World Cup and the Olympics to esports finals: ten easy questions on Korean music stars who took part in big sporting events.', null, 'multiple_choice', 'easy', 'knowledge', '[{"question":"Which BTS member performed Dreamers at the 2022 FIFA World Cup opening ceremony in Qatar?","options":["Jimin","V","Jungkook","Jin"],"correct":2,"fun_fact":"Dreamers features Qatari singer Fahad Al Kubaisi and was part of the tournament''s official soundtrack.","source":"https://en.wikipedia.org/wiki/Dreamers_(Jung_Kook_song)"},{"question":"Which 2NE1 leader performed The Baddest Female at the PyeongChang 2018 Winter Olympics closing ceremony?","options":["CL","Dara","Bom","Minzy"],"correct":0,"fun_fact":"EXO also performed Growl and Power in the same concert section, and DJ Martin Garrix headlined the afterparty.","source":"https://en.wikipedia.org/wiki/2018_Winter_Olympics_closing_ceremony"},{"question":"Which girl group sang Gods, the theme song of the 2023 League of Legends World Championship?","options":["aespa","NewJeans","IVE","LE SSERAFIM"],"correct":1,"fun_fact":"The South Korean team T1 went on to win that year''s tournament.","source":"https://en.wikipedia.org/wiki/2023_League_of_Legends_World_Championship"},{"question":"Which boy group carried the PyeongChang 2018 Olympic flame together in Seoul on January 13, 2018?","options":["TXT","ENHYPEN","ATEEZ","Monsta X"],"correct":3,"fun_fact":"Their third Japanese single followed on January 31 and featured Spotlight, the first original song they recorded in Japanese.","source":"https://en.wikipedia.org/wiki/Monsta_X"},{"question":"Which band sang Hand in Hand, the theme song of the 1988 Seoul Olympics?","options":["Koreana","Seo Taiji and Boys","H.O.T.","Sechs Kies"],"correct":0,"fun_fact":"The song was composed and produced by Giorgio Moroder, with English lyrics by Tom Whitlock.","source":"https://en.wikipedia.org/wiki/Hand_in_Hand_(Olympic_theme_song)"},{"question":"Which two K-pop boy groups performed at the closing ceremony of the 2018 Asian Games in Jakarta?","options":["EXO and NCT 127","SHINee and WINNER","BTS and GOT7","Super Junior and iKON"],"correct":3,"fun_fact":"Indian singer Sidharth Slathia also performed at the ceremony, alongside Indonesian artists.","source":"https://en.wikipedia.org/wiki/2018_Asian_Games_closing_ceremony"},{"question":"Which group sang Only One, the official theme song of the 2014 Incheon Asian Games?","options":["TVXQ","Super Junior","JYJ","SHINee"],"correct":2,"fun_fact":"They performed it in a medley with Flame and Empty during the torch relay section of the opening ceremony.","source":"https://en.wikipedia.org/wiki/2014_Asian_Games_opening_ceremony"},{"question":"Which singer closed the 2014 Asian Games opening ceremony alongside pianist Lang Lang?","options":["Rain","BoA","G-Dragon","Psy"],"correct":3,"fun_fact":"He performed a remake of his early single Champion and his global hit Gangnam Style.","source":"https://en.wikipedia.org/wiki/2014_Asian_Games_opening_ceremony"},{"question":"Which BTS member served as a torchbearer for the Paris 2024 Summer Olympics?","options":["RM","Suga","Jin","J-Hope"],"correct":2,"fun_fact":"He carried the flame for the South Korean delegation, then launched his solo variety show Run Jin in August 2024.","source":"https://en.wikipedia.org/wiki/Jin_(singer)"},{"question":"Which EXO member represented Heartsteel, the virtual boy band unveiled at the 2023 League of Legends Worlds?","options":["Kai","Baekhyun","Chanyeol","D.O."],"correct":1,"fun_fact":"The virtual group''s other human counterparts were ØZI, Tobi Lou and Cal Scruby.","source":"https://en.wikipedia.org/wiki/2023_League_of_Legends_World_Championship"}]'::jsonb, '2026-10-21'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Dreamers_(Jung_Kook_song) ; https://en.wikipedia.org/wiki/2018_Winter_Olympics_closing_ceremony ; https://en.wikipedia.org/wiki/2023_League_of_Legends_World_Championship ; https://en.wikipedia.org/wiki/Monsta_X ; https://en.wikipedia.org/wiki/Ateez ; https://en.wikipedia.org/wiki/Tomorrow_X_Together ; https://en.wikipedia.org/wiki/Enhypen ; https://en.wikipedia.org/wiki/Hand_in_Hand_(Olympic_theme_song) ; https://en.wikipedia.org/wiki/2018_Asian_Games_closing_ceremony ; https://en.wikipedia.org/wiki/2014_Asian_Games_opening_ceremony ; https://en.wikipedia.org/wiki/Jin_(singer). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('BTS: The Dynamite to Proof Era', 'Ten questions on BTS from 2020 to 2022: Dynamite, BE and Life Goes On, Butter, Permission to Dance, My Universe and Proof.', 1, 'multiple_choice', 'medium', 'era', '[{"question":"In 2020, Dynamite made BTS the first all-South Korean act to top which chart?","options":["Billboard 200","Billboard Hot 100","Oricon Albums Chart","Circle Album Chart"],"correct":1,"fun_fact":"Dynamite was the band''s first song fully recorded in English, and it sold 265,000 downloads in its first US week.","source":"https://en.wikipedia.org/wiki/Dynamite_(BTS_song)"},{"question":"Dynamite earned BTS their first Grammy nomination. In which category?","options":["Best New Artist","Album of the Year","Best Pop Duo/Group Performance","Record of the Year"],"correct":2,"fun_fact":"The nomination, at the 63rd Annual Grammy Awards, made BTS the first Korean pop act nominated for a Grammy.","source":"https://en.wikipedia.org/wiki/Dynamite_(BTS_song)"},{"question":"Which song was the lead single of BE, released in November 2020?","options":["Life Goes On","Blue & Grey","Telepathy","Fly to My Room"],"correct":0,"fun_fact":"Life Goes On became the first primarily Korean-language song to debut at No. 1 on the Billboard Hot 100.","source":"https://en.wikipedia.org/wiki/Life_Goes_On_(BTS_song)"},{"question":"Which member directed the music video for Life Goes On, the BE lead single?","options":["RM","V","Jimin","Jungkook"],"correct":3,"fun_fact":"On BE, Jimin handled A&R as the link between the group and their label, while V and RM supervised graphics and design.","source":"https://en.wikipedia.org/wiki/Be_(BTS_album)"},{"question":"How many non-consecutive weeks did Butter spend at No. 1 on the Billboard Hot 100?","options":["Three","Six","Ten","Seventeen"],"correct":2,"fun_fact":"Its video drew 108.2 million YouTube views in 24 hours and set four Guinness World Records.","source":"https://en.wikipedia.org/wiki/Butter_(song)"},{"question":"Which British singer is among the writers of Permission to Dance (2021)?","options":["Harry Styles","Ed Sheeran","Sam Smith","Lewis Capaldi"],"correct":1,"fun_fact":"Its video uses sign language in the choreography, and BTS performed it at the 76th United Nations General Assembly.","source":"https://en.wikipedia.org/wiki/Permission_to_Dance"},{"question":"Which band teamed up with BTS on My Universe, a Billboard Hot 100 No. 1 in 2021?","options":["Maroon 5","Imagine Dragons","OneRepublic","Coldplay"],"correct":3,"fun_fact":"No song billed to two lead groups had reached No. 1 on the Hot 100 before it, and it gave BTS their sixth US chart-topper.","source":"https://en.wikipedia.org/wiki/My_Universe_(song)"},{"question":"Which song was the lead single of Proof, BTS''s 2022 anthology album?","options":["Yet to Come","Run BTS","For Youth","Young Love"],"correct":0,"fun_fact":"It was BTS''s first original Korean-language single since Life Goes On, co-written by RM, Suga and J-Hope.","source":"https://en.wikipedia.org/wiki/Yet_to_Come_(The_Most_Beautiful_Moment)"},{"question":"In which US city did the Permission to Dance on Stage concerts end in April 2022?","options":["Los Angeles","Las Vegas","New York","Chicago"],"correct":1,"fun_fact":"BTS played four nights to about 200,000 fans at Allegiant Stadium, setting the all-time Billboard box office record for Las Vegas.","source":"https://en.wikipedia.org/wiki/Permission_to_Dance_on_Stage"},{"question":"In October 2022, BTS gave a concert in which city to support its bid to host the 2030 World Expo?","options":["Busan","Seoul","Incheon","Daegu"],"correct":0,"fun_fact":"The October 15 concert was held under the banner Yet to Come.","source":"https://en.wikipedia.org/wiki/BTS"}]'::jsonb, '2026-10-22'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Dynamite_(BTS_song) ; https://en.wikipedia.org/wiki/Life_Goes_On_(BTS_song) ; https://en.wikipedia.org/wiki/Be_(BTS_album) ; https://en.wikipedia.org/wiki/Butter_(song) ; https://en.wikipedia.org/wiki/Permission_to_Dance ; https://en.wikipedia.org/wiki/My_Universe_(song) ; https://en.wikipedia.org/wiki/Proof_(album) ; https://en.wikipedia.org/wiki/Yet_to_Come_(The_Most_Beautiful_Moment) ; https://en.wikipedia.org/wiki/Permission_to_Dance_on_Stage ; https://en.wikipedia.org/wiki/BTS. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Weather and Season Songs', 'Spring Day, Hot Summer, The First Snow: ten easy questions on K-pop songs and albums named after weather and seasons.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Which group released Spring Day in February 2017?","options":["EXO","BTS","SEVENTEEN","GOT7"],"correct":1,"fun_fact":"RM and Suga are among its writers, and it led You Never Walk Alone, the 2017 repackage of Wings.","source":"https://en.wikipedia.org/wiki/Spring_Day_(song)"},{"question":"EXO''s 2013 winter EP Miracles in December has a track named after a snowfall. Which one?","options":["The First Snow","Christmas Day","The Star","My Turn to Cry"],"correct":0,"fun_fact":"It became a Korean favorite for the first snowfall of the year, and in 2023, a decade on, it climbed to No. 1 on the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/Miracles_in_December"},{"question":"Which BIGBANG song has a Korean title that means Spring Summer Fall Winter?","options":["Haru Haru","Lies","Still Life","Fantastic Baby"],"correct":2,"fun_fact":"Released on April 5, 2022, it was their first release in four years, following Flower Road in 2018.","source":"https://en.wikipedia.org/wiki/Still_Life_(BigBang_song)"},{"question":"Which Stray Kids lead single from August 2021 takes its English title from thunder?","options":["God''s Menu","Maniac","S-Class","Thunderous"],"correct":3,"fun_fact":"Its Korean title, Sori-kkun, refers to a pansori singer, and the track mixes trap with Korean traditional music.","source":"https://en.wikipedia.org/wiki/Thunderous"},{"question":"Which girl group released a Korean version of Hot Summer in June 2011?","options":["f(x)","Wonder Girls","KARA","Girls'' Generation"],"correct":0,"fun_fact":"The song was first recorded by German pop group Monrose in 2007.","source":"https://en.wikipedia.org/wiki/Hot_Summer_(song)"},{"question":"Which Red Velvet summer EP from August 2018 was led by Power Up?","options":["The Red Summer","Rookie","The ReVe Festival","Summer Magic"],"correct":3,"fun_fact":"It also included an English version of Bad Boy, the group''s first song released in English.","source":"https://en.wikipedia.org/wiki/Summer_Magic_(EP)"},{"question":"What was the title of the TWICE summer reissue from July 2018, led by Dance the Night Away?","options":["Twicetagram","Fancy You","Summer Nights","Page Two"],"correct":2,"fun_fact":"It expanded their EP What Is Love?, and the lead single''s music video was filmed in Japan.","source":"https://en.wikipedia.org/wiki/Summer_Nights_(EP)"},{"question":"Which girl group released Sunny Summer in July 2018?","options":["Apink","Oh My Girl","Lovelyz","GFRIEND"],"correct":3,"fun_fact":"Source Music released it as the title track of the group''s seventh EP, also named Sunny Summer.","source":"https://en.wikipedia.org/wiki/Sunny_Summer_(song)"},{"question":"Which Girls'' Generation member released the solo song Rain in February 2016?","options":["Yoona","Tiffany","Taeyeon","Seohyun"],"correct":2,"fun_fact":"Rain and its B-side Secret opened SM Station, the weekly digital music project of SM Entertainment.","source":"https://en.wikipedia.org/wiki/Rain_(Taeyeon_song)"},{"question":"Which boy group released Spring Breeze as the lead single of its only studio album in 2018?","options":["X1","Wanna One","NU''EST","Golden Child"],"correct":1,"fun_fact":"The album was the group''s final release before it disbanded in January 2019.","source":"https://en.wikipedia.org/wiki/1%C2%B9%C2%B9%3D1_(Power_of_Destiny)"}]'::jsonb, '2026-10-23'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Spring_Day_(song) ; https://en.wikipedia.org/wiki/Miracles_in_December ; https://en.wikipedia.org/wiki/Still_Life_(BigBang_song) ; https://en.wikipedia.org/wiki/Thunderous ; https://en.wikipedia.org/wiki/Hot_Summer_(song) ; https://en.wikipedia.org/wiki/Summer_Magic_(EP) ; https://en.wikipedia.org/wiki/Summer_Nights_(EP) ; https://en.wikipedia.org/wiki/Sunny_Summer_(song) ; https://en.wikipedia.org/wiki/Rain_(Taeyeon_song) ; https://en.wikipedia.org/wiki/1%C2%B9%C2%B9%3D1_(Power_of_Destiny). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop First Studio Albums True or False', 'Ten true or false statements about the first full-length albums of K-pop groups, from Super Junior and BIGBANG to i-dle.', null, 'true_false', 'easy', 'true_false', '[{"question":"The first studio album by Girls'' Generation was The Boys.","correct":false,"fun_fact":"Their first studio album was the self-titled Girls'' Generation, released by SM Entertainment on November 1, 2007.","source":"https://en.wikipedia.org/wiki/Girls%27_Generation_(2007_album)"},{"question":"BIGBANG''s first studio album, BigBang Vol.1, came out in 2006.","correct":true,"fun_fact":"It was released on December 22, 2006, through YG Entertainment and went on to sell more than 110,000 copies.","source":"https://en.wikipedia.org/wiki/Big_Bang_Vol.1"},{"question":"SHINee''s first studio album was The Shinee World.","correct":true,"fun_fact":"Released in August 2008, it was led by Love Like Oxygen, a remake of a song by Danish singer Martin Hoberg Hedegaard.","source":"https://en.wikipedia.org/wiki/The_Shinee_World"},{"question":"2NE1''s first studio album was Crush.","correct":false,"fun_fact":"Their first studio album was To Anyone in 2010; Crush, released in 2014, was their second and final one.","source":"https://en.wikipedia.org/wiki/Crush_(2NE1_album)"},{"question":"EXO''s first studio album was XOXO.","correct":true,"fun_fact":"XOXO came out in June 2013 and won Album of the Year at the 2013 Mnet Asian Music Awards.","source":"https://en.wikipedia.org/wiki/XOXO_(Exo_album)"},{"question":"BTS''s first Korean studio album was Wings.","correct":false,"fun_fact":"Their debut studio album was Dark & Wild, released in August 2014 with Danger as its lead single.","source":"https://en.wikipedia.org/wiki/Dark_%26_Wild"},{"question":"MAMAMOO''s first studio album was Melting.","correct":true,"fun_fact":"Melting arrived on February 26, 2016, and its single You''re the Best gave the group its first music show win.","source":"https://en.wikipedia.org/wiki/Melting_(album)"},{"question":"Super Junior''s first studio album was Sorry, Sorry.","correct":false,"fun_fact":"Their first album was Twins, released on November 28, 2005; Sorry, Sorry, from March 2009, was their third.","source":"https://en.wikipedia.org/wiki/Super_Junior"},{"question":"Stray Kids'' first studio album was 5-Star.","correct":false,"fun_fact":"Their first full-length album was Go Live, released on June 17, 2020, with the lead single God''s Menu.","source":"https://en.wikipedia.org/wiki/Go_Live_(album)"},{"question":"i-dle''s first studio album, released when the group was still called (G)I-DLE, was I Never Die.","correct":true,"fun_fact":"Released in 2022, it was led by Tomboy, which reached No. 1 on the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/I-dle"}]'::jsonb, '2026-10-24'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Girls%27_Generation_(2007_album) ; https://en.wikipedia.org/wiki/Girls%27_Generation ; https://en.wikipedia.org/wiki/Big_Bang_Vol.1 ; https://en.wikipedia.org/wiki/The_Shinee_World ; https://en.wikipedia.org/wiki/Crush_(2NE1_album) ; https://en.wikipedia.org/wiki/To_Anyone ; https://en.wikipedia.org/wiki/XOXO_(Exo_album) ; https://en.wikipedia.org/wiki/Exo ; https://en.wikipedia.org/wiki/Dark_%26_Wild ; https://en.wikipedia.org/wiki/Wings_(BTS_album) ; https://en.wikipedia.org/wiki/Melting_(album) ; https://en.wikipedia.org/wiki/Super_Junior ; https://en.wikipedia.org/wiki/Go_Live_(album) ; https://en.wikipedia.org/wiki/5-Star_(Stray_Kids_album) ; https://en.wikipedia.org/wiki/I-dle. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('Stray Kids: From 5-Star to KARMA', 'Ten questions on Stray Kids since 2023: 5-Star, Rock-Star, ATE, Hop, KARMA, the Japanese releases and the Dominate stadium tour.', 3, 'multiple_choice', 'medium', 'group_specific', '[{"question":"Before its June 2023 release, 5-Star set a K-pop preorder record. Roughly how many preorders did it gather?","options":["About 1.5 million","About 2.4 million","About 5.1 million","About 8 million"],"correct":2,"fun_fact":"The 12-track album was the group''s first release in eight months, according to Yonhap.","source":"https://en.yna.co.kr/view/AEN20230602003200315"},{"question":"Which song, the lead single of Rock-Star, became Stray Kids'' first entry on the Billboard Hot 100?","options":["S-Class","Lalalala","Chk Chk Boom","Ceremony"],"correct":1,"fun_fact":"Its Korean title, Rak, means pleasure, and it entered the Hot 100 at number 90.","source":"https://en.wikipedia.org/wiki/Lalalala"},{"question":"Which two actors appear in the Chk Chk Boom music video, dressed as Deadpool and Wolverine?","options":["Ryan Reynolds and Hugh Jackman","Chris Evans and Chris Hemsworth","Tom Holland and Zendaya","Keanu Reeves and Halle Berry"],"correct":0,"fun_fact":"I.N had said he wanted to try Latin music in the group''s own colors, and the song mixes hip-hop with reggaeton.","source":"https://en.wikipedia.org/wiki/Chk_Chk_Boom"},{"question":"Which world tour did Stray Kids launch in August 2024 in support of ATE?","options":["Maniac","Dominate","5-Star Dome Tour","Run It"],"correct":1,"fun_fact":"JYP Entertainment said the title reflects the group''s ambition to dominate the stage as global top artists.","source":"https://en.wikipedia.org/wiki/Dominate_World_Tour"},{"question":"On the Dominate tour, Stray Kids became the first act ever to perform at which Toronto venue?","options":["Scotiabank Arena","BMO Field","Rogers Stadium","Massey Hall"],"correct":2,"fun_fact":"The tour''s concert film, The Dominate Experience, was shot at SoFi Stadium and premiered in February 2026.","source":"https://en.wikipedia.org/wiki/Dominate_World_Tour"},{"question":"Hop, released in December 2024, was marketed as the first record in which Stray Kids series?","options":["SKZhop Hiptape","SKZ It Tape","SKZ-Replay","SKZ-Player"],"correct":0,"fun_fact":"Its lead single was Walkin on Water, while Canadian rapper Tablo is featured on a different track, U.","source":"https://en.wikipedia.org/wiki/Hop_(mixtape)"},{"question":"Which song was the lead single of KARMA, the studio album Stray Kids released in August 2025?","options":["Walkin on Water","Chk Chk Boom","Lalalala","Ceremony"],"correct":3,"fun_fact":"Its futuristic sports-themed music video features a cameo from professional gamer Faker.","source":"https://en.wikipedia.org/wiki/Ceremony_(Stray_Kids_song)"},{"question":"When KARMA debuted at No. 1 on the Billboard 200 in 2025, which No. 1 was it for Stray Kids?","options":["Their fifth","Their sixth","Their seventh","Their eighth"],"correct":2,"fun_fact":"It also put Stray Kids ahead of BTS for the most Billboard 200 No. 1s by a K-pop act.","source":"https://www.koreajoongangdaily.com/entertainment/stray-kids-earns-7th-billboard-200-no-1/12269264"},{"question":"Which Japanese singer-songwriter is featured on Social Path, from Stray Kids'' 2023 Japanese EP?","options":["Ado","LiSA","Aimyon","Utada Hikaru"],"correct":1,"fun_fact":"The EP topped the Oricon Albums Chart and was certified million by the Recording Industry Association of Japan.","source":"https://en.wikipedia.org/wiki/Social_Path_/_Super_Bowl_(Japanese_Ver.)"},{"question":"Night and Falling Up, singles from the 2024 Japanese album Giant, are themes for which anime?","options":["Jujutsu Kaisen","Spy x Family","Demon Slayer","Tower of God"],"correct":3,"fun_fact":"The album reached No. 1 on the Oricon Albums Chart and on Billboard Japan Hot Albums, and went double platinum in Japan.","source":"https://en.wikipedia.org/wiki/Giant_(Stray_Kids_album)"}]'::jsonb, '2026-10-25'::date, 'verified', now(), 'Sources: https://en.yna.co.kr/view/AEN20230602003200315 ; https://en.wikipedia.org/wiki/5-Star_(Stray_Kids_album) ; https://en.wikipedia.org/wiki/Lalalala ; https://en.wikipedia.org/wiki/Rock-Star_(EP) ; https://en.wikipedia.org/wiki/Chk_Chk_Boom ; https://en.wikipedia.org/wiki/Ate_(EP) ; https://en.wikipedia.org/wiki/Dominate_World_Tour ; https://en.wikipedia.org/wiki/Hop_(mixtape) ; https://en.wikipedia.org/wiki/Ceremony_(Stray_Kids_song) ; https://en.wikipedia.org/wiki/Karma_(Stray_Kids_album) ; https://www.koreajoongangdaily.com/entertainment/stray-kids-earns-7th-billboard-200-no-1/12269264 ; https://en.wikipedia.org/wiki/Social_Path_/_Super_Bowl_(Japanese_Ver.) ; https://en.wikipedia.org/wiki/Giant_(Stray_Kids_album) ; https://en.wikipedia.org/wiki/Stray_Kids. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('SEVENTEEN: The Face the Sun Era', 'Relive SEVENTEEN''s 2022 run: Face the Sun, Hot, Darl+ing, the Inner Shadows trailers, Sector 17 with _World and the Be the Sun tour.', 7, 'multiple_choice', 'medium', 'era', '[{"question":"Which song was the lead single of SEVENTEEN''s 2022 album Face the Sun?","options":["Rock with You","Hot","Ready to Love","Super"],"correct":1,"fun_fact":"Woozi co-wrote it with writers including Bumzu and August Rigo, and the track is built around Western-style guitar riffs.","source":"https://en.wikipedia.org/wiki/Hot_(Seventeen_song)"},{"question":"Face the Sun is which full-length studio album in SEVENTEEN''s discography?","options":["Their second","Their third","Their fourth","Their fifth"],"correct":2,"fun_fact":"It was the group''s first studio album since An Ode in 2019, and Pledis released it through YG Plus.","source":"https://en.wikipedia.org/wiki/Face_the_Sun"},{"question":"Which song, released ahead of Face the Sun in April 2022, was SEVENTEEN''s first English-lyric single?","options":["Darl+ing","_World","Cheers","Domino"],"correct":0,"fun_fact":"Dedicated to the group''s international fans, it topped the iTunes music charts in 34 countries after its April release.","source":"https://www.koreajoongangdaily.com/entertainment/celeb-seventeen-is-staying-strong-even-seven-years-in/10396221"},{"question":"Roughly how many pre-orders did Face the Sun collect before its release?","options":["About 1 million","About 5 million","About 500,000","About 2 million"],"correct":3,"fun_fact":"It beat the group''s previous pre-order best of 1.41 million, set by their EP Attacca.","source":"https://en.wikipedia.org/wiki/Face_the_Sun"},{"question":"At what position did Face the Sun debut on the US Billboard 200, the group''s first top 10 there?","options":["No. 7","No. 1","No. 15","No. 20"],"correct":0,"fun_fact":"It earned 44,000 equivalent album units in its first week, and 42,000 of those came from album sales.","source":"https://www.billboard.com/music/chart-beat/bad-bunny-un-verano-sin-ti-billboard-200-no-1-return-1235086178/"},{"question":"Which world tour did SEVENTEEN launch in 2022 to support Face the Sun?","options":["Ode to You","Follow","Right Here","Be the Sun"],"correct":3,"fun_fact":"The tour opened with two Seoul concerts on June 25 and 26, 2022, before heading to the US and Canada.","source":"https://www.koreajoongangdaily.com/entertainment/celeb-seventeen-is-staying-strong-even-seven-years-in/10396221"},{"question":"What was the title of the July 2022 repackage of Face the Sun?","options":["Attacca","Sector 17","Dream","Your Choice"],"correct":1,"fun_fact":"The repackage had already passed 1.2 million pre-orders a few days before its July 18, 2022 release.","source":"https://www.koreajoongangdaily.com/entertainment/seventeen-to-drop-repackaged-fourth-fulllength-album-this-evening/10567023"},{"question":"Which song was the lead track of the repackage Sector 17?","options":["Cheers","Circles","_World","Fallin'' Flower"],"correct":2,"fun_fact":"Pledis explained that the underscore stands for all the open ways SEVENTEEN and their fans can interpret the world.","source":"https://www.koreajoongangdaily.com/entertainment/seventeen-to-drop-repackaged-fourth-fulllength-album-this-evening/10567023"},{"question":"Which 13-part YouTube trailer series did SEVENTEEN start on April 26, 2022 to tease Face the Sun?","options":["Inner Shadows","Going Seventeen","Power of Love","Caratland"],"correct":0,"fun_fact":"According to Hoshi, the album marked the group leaving its old image behind and growing up.","source":"https://en.wikipedia.org/wiki/Face_the_Sun"},{"question":"Hot won first place on M Countdown in June 2022. On which KBS music show did it also win?","options":["Inkigayo","Music Bank","Show! Music Core","The Show"],"correct":1,"fun_fact":"The song was also nominated for Best K-Pop at the MTV Video Music Awards.","source":"https://en.wikipedia.org/wiki/Hot_(Seventeen_song)"}]'::jsonb, '2026-10-26'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Hot_(Seventeen_song) ; https://en.wikipedia.org/wiki/Face_the_Sun ; https://www.koreajoongangdaily.com/entertainment/celeb-seventeen-is-staying-strong-even-seven-years-in/10396221 ; https://www.koreajoongangdaily.com/entertainment/seventeens-face-the-sun-gets-2-million-orders/10296387 ; https://www.billboard.com/music/pop/seventeen-darling-english-single-video-1235059079/ ; https://www.billboard.com/music/chart-beat/bad-bunny-un-verano-sin-ti-billboard-200-no-1-return-1235086178/ ; https://www.koreajoongangdaily.com/entertainment/seventeen-to-drop-repackaged-fourth-fulllength-album-this-evening/10567023 ; https://en.wikipedia.org/wiki/Seventeen_(South_Korean_band). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Hits and Their Albums', 'Match ten famous K-pop singles to the albums they belong to, with one hit each from ten groups, from BIGBANG and Apink to IVE.', null, 'multiple_choice', 'easy', 'knowledge', '[{"question":"Baddie, released in October 2023, was a single from which IVE release?","options":["Love Dive","I''ve IVE","I''ve Mine","After Like"],"correct":2,"fun_fact":"It spent three weeks at No. 1 on the Circle Digital Chart, giving IVE a fifth chart-topper there.","source":"https://en.wikipedia.org/wiki/Baddie_(song)"},{"question":"Pink Venom was the lead single of which BLACKPINK album?","options":["Born Pink","The Album","Square Up","Kill This Love"],"correct":0,"fun_fact":"It held No. 1 on the Billboard Global 200 for two weeks; no girl group had led that chart before.","source":"https://en.wikipedia.org/wiki/Pink_Venom"},{"question":"Talk That Talk, released in August 2022, was the lead single of which TWICE EP?","options":["Taste of Love","Fancy You","Ready to Be","Between 1&2"],"correct":3,"fun_fact":"Collapsedone, who had co-composed earlier TWICE singles like Knock Knock and The Feels, wrote the music with Like; Danke penned the lyrics.","source":"https://en.wikipedia.org/wiki/Talk_That_Talk_(Twice_song)"},{"question":"Mr. Chu, from 2014, was the lead single of which Apink mini album?","options":["Secret Garden","Pink Blossom","Une Année","Pink Luv"],"correct":1,"fun_fact":"Composed by Duble Sidekick, the song earned Apink six music show trophies.","source":"https://en.wikipedia.org/wiki/Mr._Chu"},{"question":"Supernova was the lead single of which aespa album?","options":["Savage","Armageddon","My World","Drama"],"correct":1,"fun_fact":"It was aespa''s first song to top the Circle Digital Chart, where it spent eleven non-consecutive weeks at No. 1.","source":"https://en.wikipedia.org/wiki/Supernova_(Aespa_song)"},{"question":"Ko Ko Bop, from 2017, was the lead single of which EXO studio album?","options":["XOXO","Don''t Mess Up My Tempo","Exodus","The War"],"correct":3,"fun_fact":"SM Entertainment released the song in two versions, one in Korean and one in Chinese.","source":"https://en.wikipedia.org/wiki/Ko_Ko_Bop"},{"question":"Red Flavor was the lead single of which Red Velvet EP?","options":["The Red Summer","Russian Roulette","The Perfect Red Velvet","The ReVe Festival: Day 1"],"correct":0,"fun_fact":"Written by Kenzie, the summery dance-pop song arrived in July 2017 with a fruit-filled music video.","source":"https://en.wikipedia.org/wiki/Red_Flavor"},{"question":"Wannabe was the lead single of which ITZY release?","options":["It''z Icy","Guess Who","It''z Me","Crazy in Love"],"correct":2,"fun_fact":"Galactika, the team that made ITZY''s debut hit Dalla Dalla, handled both the writing and the production.","source":"https://en.wikipedia.org/wiki/Wannabe_(Itzy_song)"},{"question":"Fantastic Baby came out alongside which 2012 BIGBANG EP?","options":["Remember","Made","Tonight","Alive"],"correct":3,"fun_fact":"BIGBANG''s G-Dragon and T.O.P co-wrote it with Teddy Park, and G-Dragon and Teddy also composed and produced it.","source":"https://en.wikipedia.org/wiki/Fantastic_Baby"},{"question":"Kick It, from 2020, was the lead single of which NCT 127 studio album?","options":["Neo Zone","Sticker","Fact Check","2 Baddies"],"correct":0,"fun_fact":"Its Korean title means hero, and its music video has a martial arts theme.","source":"https://en.wikipedia.org/wiki/Kick_It_(NCT_127_song)"}]'::jsonb, '2026-10-27'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Baddie_(song) ; https://en.wikipedia.org/wiki/Pink_Venom ; https://en.wikipedia.org/wiki/Talk_That_Talk_(Twice_song) ; https://en.wikipedia.org/wiki/Mr._Chu ; https://en.wikipedia.org/wiki/Supernova_(Aespa_song) ; https://en.wikipedia.org/wiki/Ko_Ko_Bop ; https://en.wikipedia.org/wiki/Red_Flavor ; https://en.wikipedia.org/wiki/Wannabe_(Itzy_song) ; https://en.wikipedia.org/wiki/Fantastic_Baby ; https://en.wikipedia.org/wiki/Kick_It_(NCT_127_song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Hitmakers and Their Groups', 'Who is behind the hits? Match ten K-pop producers and songwriting teams, from Pdogg and Teddy Park to Black Eyed Pilseung, with their groups.', null, 'multiple_choice', 'medium', 'fun', '[{"question":"The production duo Black Eyed Pilseung wrote Like Ooh-Ahh, Cheer Up and TT for which group?","options":["Red Velvet","Oh My Girl","GFRIEND","TWICE"],"correct":3,"fun_fact":"The duo later set up High Up Entertainment and debuted their own girl group, STAYC, in November 2020.","source":"https://en.wikipedia.org/wiki/Black_Eyed_Pilseung"},{"question":"Which Big Hit producer helped bring a young RM to the label and went on to become BTS''s main producer?","options":["Teddy Park","Pdogg","Kenzie","Yoo Young-jin"],"correct":1,"fun_fact":"KOMCA named him the highest-earning songwriter and composer of 2018 at its February 2019 awards.","source":"https://en.wikipedia.org/wiki/Pdogg"},{"question":"London duo LDN Noise is best known in K-pop for tracks for groups from which agency?","options":["SM Entertainment","YG Entertainment","HYBE","JYP Entertainment"],"correct":0,"fun_fact":"Greg Bonnick and Hayden Chapman got their first writing credit with Chris Brown''s Turn Up the Music, a UK No. 1 in 2012.","source":"https://en.wikipedia.org/wiki/LDN_Noise"},{"question":"Longtime SM songwriter Kenzie wrote which Girls'' Generation debut song?","options":["Genie","Gee","Into the New World","Run Devil Run"],"correct":2,"fun_fact":"Kenzie graduated from Berklee College of Music in 1999, where she majored in music production and engineering.","source":"https://en.wikipedia.org/wiki/Kenzie_(songwriter)"},{"question":"Longtime SM producer Yoo Young-jin, who left the label in 2023, wrote songs for which first-generation boy band?","options":["H.O.T.","g.o.d","Sechs Kies","NRG"],"correct":0,"fun_fact":"His credits run from S.E.S. and BoA to TVXQ, Girls'' Generation, SHINee, EXO, Red Velvet, NCT and aespa.","source":"https://en.wikipedia.org/wiki/Yoo_Young-jin"},{"question":"Sweetune, a team known for 1980s-style synth-pop, produced the albums Lupin and Step for which group?","options":["Wonder Girls","2NE1","Kara","Miss A"],"correct":2,"fun_fact":"Founded by Han Jae-ho and Kim Seung-soo, the team also produced for Infinite, Rainbow and Nine Muses.","source":"https://en.wikipedia.org/wiki/Sweetune"},{"question":"Duble Sidekick rose to fame in 2012 by producing the EP 100% Ver. for which boy band?","options":["2PM","Beast","Infinite","MBLAQ"],"correct":3,"fun_fact":"The duo pairs lyricist Park Jang-geun with composer Mikey, a former member of the group One Way.","source":"https://en.wikipedia.org/wiki/Duble_Sidekick"},{"question":"Producer Ryan S. Jhun''s first hands-on K-pop track was Lucifer. Which group recorded it?","options":["Super Junior","SHINee","TVXQ","EXO"],"correct":1,"fun_fact":"His first released song was Chitty Chitty Bang Bang, on Lee Hyori''s 2010 album H-Logic.","source":"https://en.wikipedia.org/wiki/Ryan_S._Jhun"},{"question":"Before producing for YG Entertainment, Teddy Park debuted in 1998 as a member of which hip hop group?","options":["Jinusean","1TYM","Epik High","Drunken Tiger"],"correct":1,"fun_fact":"He went on to produce the KPop Demon Hunters soundtrack, and its song Golden brought him an Academy Award for Best Original Song.","source":"https://en.wikipedia.org/wiki/Teddy_Park"},{"question":"J.Y. Park co-wrote Nobody, which took him onto the Billboard Hot 100 in 2009. Which group sang it?","options":["Miss A","2PM","Girls'' Generation","Wonder Girls"],"correct":3,"fun_fact":"Park and Rainstone became the first Korean songwriters on the Hot 100 when the song debuted at No. 76 in October 2009.","source":"https://en.wikipedia.org/wiki/J._Y._Park"}]'::jsonb, '2026-10-28'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Black_Eyed_Pilseung ; https://en.wikipedia.org/wiki/Pdogg ; https://en.wikipedia.org/wiki/LDN_Noise ; https://en.wikipedia.org/wiki/Kenzie_(songwriter) ; https://en.wikipedia.org/wiki/Yoo_Young-jin ; https://en.wikipedia.org/wiki/Sweetune ; https://en.wikipedia.org/wiki/Duble_Sidekick ; https://en.wikipedia.org/wiki/Ryan_S._Jhun ; https://en.wikipedia.org/wiki/Teddy_Park ; https://en.wikipedia.org/wiki/J._Y._Park. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('ENHYPEN: Sweet Venom to The Sin Quiz', 'Ten easy questions on ENHYPEN''s 2023 to 2026 releases: Orange Blood, Romance: Untold, Desire: Unleash, The Sin series and a first Billboard No. 1.', 15, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which song was the title track of ENHYPEN''s November 2023 EP Orange Blood?","options":["Sweet Venom","Bite Me","Polaroid Love","Fever"],"correct":0,"fun_fact":"Hanteo counted more than 1.38 million copies of Orange Blood sold on release day alone.","source":"https://en.wikipedia.org/wiki/Orange_Blood"},{"question":"At San Diego Comic-Con 2026, ENHYPEN shared a panel with actors from which vampire film series?","options":["Hotel Transylvania","Blade","Twilight","Underworld"],"correct":2,"fun_fact":"On the panel, the members talked about why vampire stories keep drawing in each new generation.","source":"https://en.wikipedia.org/wiki/Enhypen"},{"question":"What was the lead single of ENHYPEN''s July 2024 studio album Romance: Untold?","options":["Knife","XO (Only If You Say Yes)","Bloody Paradise","Sweet Venom"],"correct":1,"fun_fact":"The album was teased with a short film made in collaboration with director Lee Chung-hyun.","source":"https://en.wikipedia.org/wiki/Romance:_Untold"},{"question":"Which song led Romance: Untold -Daydream-, the reissue ENHYPEN released in November 2024?","options":["Daydream","Loose","Bite Me","No Doubt"],"correct":3,"fun_fact":"Released on November 11, 2024, the reissue added two new songs to the original album.","source":"https://en.wikipedia.org/wiki/Romance:_Untold"},{"question":"Bad Desire (With or Without You), released in June 2025, is a single from which ENHYPEN EP?","options":["Desire: Unleash","Orange Blood","The Sin: Vanish","Manifesto: Day 1"],"correct":0,"fun_fact":"Its pre-orders topped 2.18 million, giving ENHYPEN a third album in the double-million club.","source":"https://en.wikipedia.org/wiki/Desire:_Unleash"},{"question":"Which US talk show hosted ENHYPEN''s first performance on American television, in April 2025?","options":["The Tonight Show Starring Jimmy Fallon","The Late Show with Stephen Colbert","Jimmy Kimmel Live!","The Kelly Clarkson Show"],"correct":2,"fun_fact":"They performed Loose, a digital single the group had released earlier that month.","source":"https://en.wikipedia.org/wiki/Enhypen"},{"question":"ENHYPEN played the Sahara Tent at which US festival in April 2025?","options":["Lollapalooza","Coachella","Governors Ball","Austin City Limits"],"correct":1,"fun_fact":"At the end of their second weekend set, they revealed the title and release date of their next EP.","source":"https://en.wikipedia.org/wiki/Enhypen"},{"question":"Which song led The Sin: Vanish, the January 2026 EP that opened ENHYPEN''s The Sin series?","options":["Knife","Bloody Paradise","No Doubt","XO (Only If You Say Yes)"],"correct":0,"fun_fact":"To tease the EP, the group launched a fictional news website called Vampire Now.","source":"https://en.wikipedia.org/wiki/The_Sin:_Vanish"},{"question":"What was the lead single of The Sin: Bliss, the EP ENHYPEN released in August 2026?","options":["Knife","Sweet Venom","No Doubt","Bloody Paradise"],"correct":3,"fun_fact":"A preview of the Brazilian funk song was first played at the group''s concert in Brazil on the Blood Saga Tour.","source":"https://en.wikipedia.org/wiki/The_Sin:_Bliss"},{"question":"Which release gave ENHYPEN their first No. 1 on the US Billboard 200, in 2026?","options":["Orange Blood","Desire: Unleash","The Sin: Bliss","The Sin: Vanish"],"correct":2,"fun_fact":"It debuted at the top with 98,000 equivalent album units, 92,000 of them from album sales.","source":"https://www.koreajoongangdaily.com/entertainment/enhypen-claims-1st-no-1-on-billboard-200-with-the-sin-bliss/12851061"}]'::jsonb, '2026-10-29'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Orange_Blood ; https://en.wikipedia.org/wiki/Romance:_Untold ; https://en.wikipedia.org/wiki/Desire:_Unleash ; https://en.wikipedia.org/wiki/Enhypen ; https://en.wikipedia.org/wiki/The_Sin:_Vanish ; https://en.wikipedia.org/wiki/The_Sin:_Bliss ; https://www.koreajoongangdaily.com/entertainment/enhypen-claims-1st-no-1-on-billboard-200-with-the-sin-bliss/12851061. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Album Chart Peaks True or False', 'True or false: where did famous K-pop albums from 10 artists peak on the Billboard 200, Korea''s Gaon chart and Japan''s Oricon?', null, 'true_false', 'medium', 'true_false', '[{"question":"NewJeans reached No. 1 on the Billboard 200 with their 2023 EP Get Up.","correct":true,"fun_fact":"Get Up was also their first Billboard 200 entry, and it made NewJeans the second K-pop girl group to top the chart, after BLACKPINK.","source":"https://en.wikipedia.org/wiki/Get_Up_(EP)"},{"question":"ATEEZ scored their first Billboard 200 No. 1 with The World EP.1: Movement.","correct":false,"fun_fact":"The World EP.1: Movement peaked at No. 3 in 2022, which still gave ATEEZ their first top 10 on the Billboard 200.","source":"https://en.wikipedia.org/wiki/The_World_EP.1:_Movement"},{"question":"TVXQ''s 2011 Japanese album Tone, released as Tohoshinki, peaked at No. 2 on the Oricon Albums Chart.","correct":false,"fun_fact":"Tone went to No. 1 on the Oricon Albums Chart with 205,000 copies sold in its first week, the group''s first original album to top it.","source":"https://en.wikipedia.org/wiki/Tone_(TVXQ_album)"},{"question":"TXT earned their first Billboard 200 No. 1 with The Name Chapter: Temptation.","correct":true,"fun_fact":"The EP opened at No. 1 with 161,500 album-equivalent units, and its pre-orders passed 2.16 million copies, a career high for the group.","source":"https://en.wikipedia.org/wiki/The_Name_Chapter:_Temptation"},{"question":"TWICE''s 2023 EP Ready to Be debuted at No. 1 on the Billboard 200.","correct":false,"fun_fact":"Ready to Be debuted at No. 2 with 153,000 units, making TWICE the first female K-pop act with three top-three albums in the US.","source":"https://en.wikipedia.org/wiki/Ready_to_Be"},{"question":"When 2NE1''s Crush debuted in 2014, it became the highest-charting Korean album on the Billboard 200.","correct":true,"fun_fact":"Crush entered at No. 61 after selling over 5,000 copies in the US in four days, making it the best-selling Korean album there at the time.","source":"https://en.wikipedia.org/wiki/Crush_(2NE1_album)"},{"question":"ENHYPEN''s 2024 album Romance: Untold reached No. 1 on the Billboard 200.","correct":false,"fun_fact":"Romance: Untold peaked at No. 2 on the Billboard 200, though it did reach No. 1 in South Korea, Japan and France.","source":"https://en.wikipedia.org/wiki/Romance:_Untold"},{"question":"Monsta X''s English-language album All About Luv reached No. 5 on the Billboard 200.","correct":true,"fun_fact":"Released on February 14, 2020, it debuted with 52,000 album-equivalent units, 50,000 of them pure album sales.","source":"https://en.wikipedia.org/wiki/All_About_Luv"},{"question":"SEVENTEEN''s 2023 EP FML debuted at No. 1 on the Billboard 200.","correct":false,"fun_fact":"FML debuted at No. 2, but the IFPI named it the best-selling album worldwide in 2023, with 6.4 million units sold.","source":"https://en.wikipedia.org/wiki/FML_(EP)"},{"question":"The Korean version of EXO''s second studio album Exodus topped the weekly Gaon album chart for four straight weeks.","correct":true,"fun_fact":"Exodus came out on March 30, 2015, with Call Me Baby as its lead single. Its Chinese-language version peaked at No. 2 on the same chart.","source":"https://en.wikipedia.org/wiki/Exodus_(Exo_album)"}]'::jsonb, '2026-10-30'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Get_Up_(EP) ; https://www.billboard.com/charts/billboard-200/2023-08-05/ ; https://en.wikipedia.org/wiki/The_World_EP.1:_Movement ; https://en.wikipedia.org/wiki/Tone_(TVXQ_album) ; https://www.wikidata.org/wiki/Q192983 ; https://en.wikipedia.org/wiki/The_Name_Chapter:_Temptation ; https://www.billboard.com/charts/billboard-200/2023-02-11/ ; https://en.wikipedia.org/wiki/Ready_to_Be ; https://en.wikipedia.org/wiki/Crush_(2NE1_album) ; https://en.wikipedia.org/wiki/Romance:_Untold ; https://www.billboard.com/charts/billboard-200/2024-07-27/ ; https://en.wikipedia.org/wiki/All_About_Luv ; https://en.wikipedia.org/wiki/FML_(EP) ; https://en.wikipedia.org/wiki/Exodus_(Exo_album). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('BLACKPINK: The Born Pink Era', 'Pink Venom, Shut Down, chart records and a record-breaking world tour: test what you remember about BLACKPINK''s 2022 to 2023 era.', 2, 'multiple_choice', 'medium', 'era', '[{"question":"Which song came out in August 2022 as the pre-release single from Born Pink?","options":["Shut Down","Pink Venom","Lovesick Girls","Typa Girl"],"correct":1,"fun_fact":"BLACKPINK performed Pink Venom at the 2022 MTV Video Music Awards, the first female K-pop group ever to perform at the show.","source":"https://en.wikipedia.org/wiki/Born_Pink"},{"question":"Which traditional Korean instrument plays the opening chords of Pink Venom?","options":["Haegeum","Janggu","Geomungo","Daegeum"],"correct":2,"fun_fact":"The track blends EDM and hip-hop with traditional Korean instruments, and the gayageum can be heard on it too.","source":"https://en.wikipedia.org/wiki/Pink_Venom"},{"question":"Pink Venom was the first song by a girl group to reach No. 1 on which Billboard chart?","options":["Billboard Hot 100","Mainstream Top 40","Hot Dance/Electronic Songs","Billboard Global 200"],"correct":3,"fun_fact":"It held the top spot for two weeks and stayed on the Global 200 for 30 weeks in total.","source":"https://en.wikipedia.org/wiki/Pink_Venom"},{"question":"The title track Shut Down loops a violin sample from which classical piece?","options":["La Campanella","Für Elise","The Four Seasons","Canon in D"],"correct":0,"fun_fact":"The sample comes from Paganini''s second violin concerto. Shut Down also became the first song by a K-pop act to top Spotify''s weekly chart.","source":"https://en.wikipedia.org/wiki/Shut_Down_(Blackpink_song)"},{"question":"Born Pink was the first album by a female group to top the Billboard 200 since which group did it in 2008?","options":["Destiny''s Child","The Pussycat Dolls","Fifth Harmony","Danity Kane"],"correct":3,"fun_fact":"Born Pink also topped the UK Albums Chart, a first for a K-pop girl group, which earned BLACKPINK two Guinness World Records.","source":"https://en.wikipedia.org/wiki/Born_Pink"},{"question":"Born Pink became the first album by a K-pop girl group to sell more than how many copies?","options":["One million","Two million","Three million","Five million"],"correct":1,"fun_fact":"It debuted at No. 1 on the Circle Album Chart with 2,141,281 copies sold in less than two days of tracking.","source":"https://en.wikipedia.org/wiki/Blackpink"},{"question":"In which city did the Born Pink World Tour open on October 15, 2022?","options":["Dallas","Bangkok","Seoul","London"],"correct":2,"fun_fact":"The tour also ended in Seoul, on September 17, 2023, after 66 concerts in 22 countries.","source":"https://en.wikipedia.org/wiki/Born_Pink_World_Tour"},{"question":"With a $330 million gross, the Born Pink World Tour broke whose record for highest-grossing female group tour?","options":["Spice Girls","Little Mix","Destiny''s Child","TLC"],"correct":0,"fun_fact":"It ranked No. 10 on Billboard''s 2023 year-end tours chart and drew 1.8 million fans over its 66 shows.","source":"https://en.wikipedia.org/wiki/Born_Pink_World_Tour"},{"question":"Which California festival did BLACKPINK headline in April 2023, a first for an Asian act?","options":["Outside Lands","Coachella","BottleRock Napa Valley","Rolling Loud California"],"correct":1,"fun_fact":"They headlined on both festival weekends, on April 15 and April 22, 2023.","source":"https://en.wikipedia.org/wiki/Blackpink"},{"question":"In July 2023, BLACKPINK became the first Korean band to headline a major UK festival. Which one?","options":["Glastonbury","Reading Festival","British Summer Time Hyde Park","Wireless Festival"],"correct":2,"fun_fact":"The London show took place on July 2, 2023, just before the encore stadium leg of the tour in France and the United States.","source":"https://en.wikipedia.org/wiki/Blackpink"}]'::jsonb, '2026-10-31'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Born_Pink ; https://en.wikipedia.org/wiki/Pink_Venom ; https://en.wikipedia.org/wiki/Shut_Down_(Blackpink_song) ; https://en.wikipedia.org/wiki/Born_Pink_World_Tour ; https://en.wikipedia.org/wiki/Blackpink ; https://www.billboard.com/lists/girl-groups-number-one-albums-billboard-200/. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop on the Billboard Charts', 'From Wonder Girls in 2009 to APT. in 2025: a hard quiz on K-pop''s first Hot 100 entries and Billboard 200 number ones.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"Which act gave K-pop its first Billboard Hot 100 entry, on the chart dated October 31, 2009?","options":["BoA","Wonder Girls","Girls'' Generation","BIGBANG"],"correct":1,"fun_fact":"The English version of Nobody entered at No. 76. A PopCrush editor credited the group''s slot opening for the Jonas Brothers'' US summer tour.","source":"https://en.wikipedia.org/wiki/Nobody_(Wonder_Girls_song)"},{"question":"Who became the first South Korean artist to place an album on the Billboard 200, in 2009?","options":["Rain","Se7en","BoA","Wonder Girls"],"correct":2,"fun_fact":"The album was her self-titled record BoA, her only English-language studio album, and it peaked at No. 127.","source":"https://en.wikipedia.org/wiki/BoA_(album)"},{"question":"Which song kept PSY''s Gangnam Style stuck at No. 2 on the Hot 100 in 2012?","options":["Call Me Maybe","Somebody That I Used to Know","We Are Never Ever Getting Back Together","One More Night"],"correct":3,"fun_fact":"Gangnam Style spent seven straight weeks at No. 2 behind Maroon 5, the highest Hot 100 peak by a South Korean artist at the time.","source":"https://en.wikipedia.org/wiki/Gangnam_Style"},{"question":"Which BTS song gave a K-pop group its first top 10 hit on the Billboard Hot 100?","options":["Fake Love","DNA","Mic Drop","Idol"],"correct":0,"fun_fact":"It was also the first K-pop song to debut inside the top 10, beating PSY''s Gentleman, which had started at No. 12.","source":"https://www.billboard.com/pro/bts-first-hot-100-top-10-k-pop-group-fake-love/"},{"question":"Which album gave K-pop its first No. 1 on the Billboard 200, in 2018?","options":["Wings","Love Yourself: Her","Love Yourself: Tear","Map of the Soul: Persona"],"correct":2,"fun_fact":"It debuted with 135,000 album-equivalent units and became BTS'' highest-charting album in a Western market at the time.","source":"https://en.wikipedia.org/wiki/Love_Yourself:_Tear"},{"question":"Which act became the first Korean act to top the Billboard 200 with its debut release, in 2019?","options":["SuperM","TXT","ITZY","Stray Kids"],"correct":0,"fun_fact":"SuperM was unveiled at Capitol Congress in August 2019, and its debut EP came out on October 4, 2019.","source":"https://en.wikipedia.org/wiki/SuperM_(EP)"},{"question":"Stray Kids'' very first Billboard 200 entry went straight to No. 1. Which release was it?","options":["Noeasy","Maxident","5-Star","Oddinary"],"correct":3,"fun_fact":"With it, Stray Kids became the third Korean act to top the Billboard 200, after BTS and SuperM.","source":"https://en.wikipedia.org/wiki/Oddinary"},{"question":"With which song did Jimin become the first South Korean soloist to debut at No. 1 on the Hot 100?","options":["Set Me Free Pt. 2","Like Crazy","Who","Filter"],"correct":1,"fun_fact":"It topped the chart dated April 8, 2023, making Jimin the fourth Asian artist to lead the Hot 100, after Kyu Sakamoto, Far East Movement and BTS.","source":"https://en.wikipedia.org/wiki/Like_Crazy_(song)"},{"question":"What was the Hot 100 peak of APT. by Rosé and Bruno Mars?","options":["No. 1","No. 8","No. 3","No. 5"],"correct":2,"fun_fact":"APT. debuted at No. 8 and climbed to No. 3 on the chart dated February 1, 2025, where it stayed for two weeks.","source":"https://en.wikipedia.org/wiki/APT._(song)"},{"question":"Which girl group''s Cupid climbed to No. 17 on the Billboard Hot 100 in 2023?","options":["NewJeans","Fifty Fifty","LE SSERAFIM","IVE"],"correct":1,"fun_fact":"Cupid first entered the Hot 100 at No. 100, making Fifty Fifty the fastest Korean act to reach the chart after debuting.","source":"https://en.wikipedia.org/wiki/Cupid_(Fifty_Fifty_song)"}]'::jsonb, '2026-11-01'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Nobody_(Wonder_Girls_song) ; https://www.billboard.com/charts/hot-100/2009-10-31/ ; https://en.wikipedia.org/wiki/BoA_(album) ; https://www.billboard.com/charts/billboard-200/2009-04-04/ ; https://en.wikipedia.org/wiki/Gangnam_Style ; https://www.billboard.com/charts/hot-100/2012-10-20/ ; https://www.billboard.com/pro/bts-first-hot-100-top-10-k-pop-group-fake-love/ ; https://www.billboard.com/charts/hot-100/2018-06-02/ ; https://en.wikipedia.org/wiki/Love_Yourself:_Tear ; https://www.billboard.com/charts/billboard-200/2018-06-02/ ; https://en.wikipedia.org/wiki/SuperM_(EP) ; https://www.billboard.com/charts/billboard-200/2019-10-19/ ; https://en.wikipedia.org/wiki/Oddinary ; https://www.billboard.com/charts/billboard-200/2022-04-02/ ; https://en.wikipedia.org/wiki/Like_Crazy_(song) ; https://www.billboard.com/charts/hot-100/2023-04-08/ ; https://en.wikipedia.org/wiki/APT._(song) ; https://www.billboard.com/charts/hot-100/2025-02-01/ ; https://en.wikipedia.org/wiki/Cupid_(Fifty_Fifty_song) ; https://www.billboard.com/charts/hot-100/2023-04-01/ ; https://www.billboard.com/charts/hot-100/2023-05-20/ ; https://en.wikipedia.org/wiki/List_of_K-pop_songs_on_the_Billboard_charts ; https://en.wikipedia.org/wiki/List_of_K-pop_albums_on_the_Billboard_charts. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('Girls'' Generation: From Gee to Forever 1', 'Gee, Genie, The Boys, Lion Heart and the TTS sub-unit: how well do you know the Girls'' Generation discography and its milestones?', 87, 'multiple_choice', 'medium', 'group_specific', '[{"question":"For how many consecutive weeks was Gee the No. 1 song on the music show Music Bank in 2009?","options":["Five","Seven","Nine","Twelve"],"correct":2,"fun_fact":"Gee was also the top-performing song of the 2000s decade on the Korean streaming platform Melon.","source":"https://en.wikipedia.org/wiki/Gee_(Girls''_Generation_song)"},{"question":"Which song was released as Girls'' Generation''s debut single in Japan in September 2010?","options":["Genie","Gee","Mr. Taxi","Paparazzi"],"correct":0,"fun_fact":"The Japanese version of Genie peaked at No. 4 on the Oricon Singles Chart.","source":"https://en.wikipedia.org/wiki/Genie_(Girls''_Generation_song)"},{"question":"Which producer helped compose and arrange The Boys, the 2011 title track?","options":["Timbaland","Teddy Riley","Pharrell Williams","Rodney Jerkins"],"correct":1,"fun_fact":"Riley also wrote the English version, which was released in the United States on December 20, 2011, through Interscope Records.","source":"https://en.wikipedia.org/wiki/The_Boys_(Girls''_Generation_song)"},{"question":"On which late-night show did Girls'' Generation make their US TV debut with The Boys in 2012?","options":["The Tonight Show with Jay Leno","Jimmy Kimmel Live!","Late Show with David Letterman","Conan"],"correct":2,"fun_fact":"They also sang it on the daytime show Live! in February 2012, about three months after performing it at an SM Town concert at Madison Square Garden.","source":"https://en.wikipedia.org/wiki/The_Boys_(Girls''_Generation_song)"},{"question":"Which award did the I Got a Boy music video win at the first YouTube Music Awards in 2013?","options":["Artist of the Year","Video of the Year","Response of the Year","Breakthrough of the Year"],"correct":1,"fun_fact":"The ceremony took place at Pier 36 in New York on November 3, 2013, and the group beat nominees such as Justin Bieber and PSY.","source":"https://en.wikipedia.org/wiki/I_Got_a_Boy_(song)"},{"question":"Which single, released in July 2015, was the lead single of the album Lion Heart?","options":["You Think","Lion Heart","Party","Catch Me If You Can"],"correct":2,"fun_fact":"Party topped the Gaon Digital Chart, and Lion Heart and You Think followed as singles in August 2015.","source":"https://en.wikipedia.org/wiki/Lion_Heart_(album)"},{"question":"The 2017 album Holiday Night was released to mark which anniversary of the group''s debut?","options":["Seventh","Tenth","Twelfth","Fifteenth"],"correct":1,"fun_fact":"Its single All Night was written by Kenzie, the songwriter behind the group''s debut single Into the New World.","source":"https://en.wikipedia.org/wiki/Holiday_Night"},{"question":"Forever 1 (2022) was Girls'' Generation''s first release after a break of how many years?","options":["Two","Three","Four","Five"],"correct":3,"fun_fact":"Forever 1 is their seventh Korean studio album, released in August 2022 for their 15th anniversary.","source":"https://en.wikipedia.org/wiki/Forever_1"},{"question":"TTS, the first Girls'' Generation sub-unit, debuted in 2012 with which EP?","options":["Holler","Dear Santa","Mr.Mr.","Twinkle"],"correct":3,"fun_fact":"Twinkle reached No. 126 on the Billboard 200, the highest peak for a K-pop album on that chart at the time.","source":"https://en.wikipedia.org/wiki/Twinkle_(EP)"},{"question":"With which album did Girls'' Generation become the first female group to win the Golden Disc Album Daesang?","options":["Oh!","Mr.Mr.","The Boys","Lion Heart"],"correct":0,"fun_fact":"Oh! was their second studio album, released in January 2010, and its repackage Run Devil Run followed that March.","source":"https://en.wikipedia.org/wiki/Oh!_(Girls''_Generation_album)"}]'::jsonb, '2026-11-02'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Gee_(Girls''_Generation_song) ; https://en.wikipedia.org/wiki/Genie_(Girls''_Generation_song) ; https://en.wikipedia.org/wiki/The_Boys_(Girls''_Generation_song) ; https://en.wikipedia.org/wiki/I_Got_a_Boy_(song) ; https://en.wikipedia.org/wiki/Lion_Heart_(album) ; https://en.wikipedia.org/wiki/Holiday_Night ; https://en.wikipedia.org/wiki/Forever_1 ; https://en.wikipedia.org/wiki/Twinkle_(EP) ; https://en.wikipedia.org/wiki/Girls''_Generation-TTS ; https://en.wikipedia.org/wiki/Oh!_(Girls''_Generation_album). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Songs With Repeated Words', 'From Bloom Bloom to Ddu-Du Ddu-Du: name the K-pop group behind each hit whose title repeats a word or a sound.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Which boy group released Bloom Bloom in 2019?","options":["ASTRO","The Boyz","ONEUS","VIXX"],"correct":1,"fun_fact":"Bloom Bloom led the group''s second single album and earned them their first music show win, on The Show in May 2019.","source":"https://en.wikipedia.org/wiki/Bloom_Bloom"},{"question":"Which boy group released Bang Bang Bang in 2015?","options":["BIGBANG","2PM","Block B","iKON"],"correct":0,"fun_fact":"Bang Bang Bang topped the Gaon Digital Chart and won Song of the Year at the 2015 Melon Music Awards.","source":"https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song)"},{"question":"Which girl group released Dun Dun in 2020?","options":["Dreamcatcher","CLC","EVERGLOW","Weeekly"],"correct":2,"fun_fact":"Dun Dun was the lead single of the group''s first EP, Reminiscence, a four-track release from February 3, 2020.","source":"https://en.wikipedia.org/wiki/Reminiscence_(EP)"},{"question":"Which boy group released Again & Again in 2009?","options":["Beast","MBLAQ","U-KISS","2PM"],"correct":3,"fun_fact":"Park Jin-young wrote and composed it, and it became the group''s first No. 1 single, from their second single album 2:00PM Time for Change.","source":"https://en.wikipedia.org/wiki/Again_%26_Again_(2PM_song)"},{"question":"Which girl group released Dumb Dumb in 2015?","options":["Oh My Girl","Lovelyz","GFRIEND","Red Velvet"],"correct":3,"fun_fact":"Dumb Dumb was the lead single of the group''s first studio album, The Red, and peaked at No. 2 on the Gaon Digital Chart.","source":"https://en.wikipedia.org/wiki/Dumb_Dumb_(Red_Velvet_song)"},{"question":"Which girl group released No No No in 2013?","options":["Apink","Girl''s Day","Secret","SISTAR"],"correct":0,"fun_fact":"No No No came out with the EP Secret Garden and peaked at No. 2 on the Billboard K-pop Hot 100.","source":"https://en.wikipedia.org/wiki/No_No_No_(Apink_song)"},{"question":"Which girl group released Bo Peep Bo Peep in 2009?","options":["Wonder Girls","KARA","T-ara","4Minute"],"correct":2,"fun_fact":"Bo Peep Bo Peep earned five weekly No. 1 awards on the music shows Music Bank and Inkigayo.","source":"https://en.wikipedia.org/wiki/Bo_Peep_Bo_Peep"},{"question":"Which girl group released Yes or Yes in 2018?","options":["MOMOLAND","TWICE","GFRIEND","Weki Meki"],"correct":1,"fun_fact":"Yes or Yes debuted at No. 1 on the Gaon Digital Chart, the group''s ninth chart-topping single in a row.","source":"https://en.wikipedia.org/wiki/Yes_or_Yes_(song)"},{"question":"Which girl group released Ddu-Du Ddu-Du in 2018?","options":["2NE1","ITZY","BLACKPINK","(G)I-DLE"],"correct":2,"fun_fact":"Its music video became the first by a K-pop group to pass two billion views on YouTube.","source":"https://en.wikipedia.org/wiki/Ddu-Du_Ddu-Du"},{"question":"Which girl group released Rum Pum Pum Pum in 2013?","options":["f(x)","Girls'' Generation","miss A","After School"],"correct":0,"fun_fact":"The song''s Korean title translates to First Wisdom Teeth, and it was the lead single of the album Pink Tape.","source":"https://en.wikipedia.org/wiki/Rum_Pum_Pum_Pum"}]'::jsonb, '2026-11-03'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Bloom_Bloom ; https://en.wikipedia.org/wiki/Bang_Bang_Bang_(BigBang_song) ; https://en.wikipedia.org/wiki/Reminiscence_(EP) ; https://en.wikipedia.org/wiki/Again_%26_Again_(2PM_song) ; https://en.wikipedia.org/wiki/Dumb_Dumb_(Red_Velvet_song) ; https://en.wikipedia.org/wiki/No_No_No_(Apink_song) ; https://en.wikipedia.org/wiki/Bo_Peep_Bo_Peep ; https://en.wikipedia.org/wiki/Yes_or_Yes_(song) ; https://en.wikipedia.org/wiki/Ddu-Du_Ddu-Du ; https://en.wikipedia.org/wiki/Rum_Pum_Pum_Pum. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('aespa: The Supernova Era', 'Relive aespa''s huge 2024: the Supernova and Armageddon releases, the Whiplash EP and the year-end awards that followed.', 5, 'multiple_choice', 'medium', 'era', '[{"question":"Which aespa song was pre-released on May 13, 2024, two weeks before the album Armageddon?","options":["Supernova","Spicy","Drama","Whiplash"],"correct":0,"fun_fact":"Its futuristic music video, where each member shows off a superpower, passed 10 million views within about 10 hours of release.","source":"https://en.wikipedia.org/wiki/Supernova_(Aespa_song)"},{"question":"Armageddon, released on May 27, 2024, was aespa''s first release of which type?","options":["Single album","EP","Studio album","Japanese single"],"correct":2,"fun_fact":"The ten-track record had passed 1.02 million copies in pre-orders by its release day.","source":"https://en.wikipedia.org/wiki/Armageddon_(Aespa_album)"},{"question":"Supernova hit No. 1 on the real-time, daily and weekly iChart rankings at once. What is that feat called?","options":["Grand slam","Hat trick","Daesang","Perfect all-kill"],"correct":3,"fun_fact":"It also became aespa''s first song to top the Circle Digital Chart, where it stayed at No. 1 for 11 non-consecutive weeks.","source":"https://en.wikipedia.org/wiki/Supernova_(Aespa_song)"},{"question":"How many grand prizes (daesang) did aespa win at the 2024 Melon Music Awards?","options":["1","2","3","4"],"correct":2,"fun_fact":"They took Artist, Album and Song of the Year among seven trophies, while Record of the Year went to (G)I-DLE, now known as i-dle.","source":"https://www.koreatimes.co.kr/entertainment/k-pop/20241201/aespas-meteoric-rise-continues-with-7-melon-awards"},{"question":"Supernova won Song of the Year at the 2024 MAMA Awards, the first MAMA held partly in which country?","options":["United Kingdom","United States","Australia","Canada"],"correct":1,"fun_fact":"The first night was at the Dolby Theatre in Los Angeles; the rest moved to the Kyocera Dome in Osaka, where aespa left with six awards.","source":"https://koreajoongangdaily.joins.com/news/2024-11-24/entertainment/kpop/Wow-Fantastic-Baby-2024-MAMA-Awards-end-with-a-Big-Bang/2184738"},{"question":"Which aespa music video won Best Music Video at the 2024 MAMA Awards?","options":["Supernova","Whiplash","Spicy","Armageddon"],"correct":3,"fun_fact":"The same video later won Best K-pop Video at the 2025 MTV Video Music Awards Japan.","source":"https://en.wikipedia.org/wiki/Armageddon_(Aespa_song)"},{"question":"Whiplash, released on October 21, 2024, is aespa''s which extended play?","options":["Third","Fourth","Fifth","Sixth"],"correct":2,"fun_fact":"Besides the title track, the six-track EP includes Kill It, Pink Hoodie, Flowers and Just Another Girl.","source":"https://en.wikipedia.org/wiki/Whiplash_(EP)"},{"question":"In March 2025, an English version of Whiplash came out alongside a remix by which DJ?","options":["Marshmello","Steve Aoki","Zedd","David Guetta"],"correct":1,"fun_fact":"The English version came out on March 27, 2025, bundled with the Aoki remix and a sped-up take of the song.","source":"https://en.wikipedia.org/wiki/Whiplash_(Aespa_song)"},{"question":"What was the name of aespa''s second world tour, launched in Seoul in June 2024?","options":["Synk: Hyper Line","Synk: Parallel Line","Synk: Aexis Line","Synk: Complaexity"],"correct":1,"fun_fact":"At the first Seoul shows each member unveiled a solo song, and the four tracks were released together on October 9, 2024.","source":"https://en.wikipedia.org/wiki/Synk:_Parallel_Line_(single_album)"},{"question":"aespa opened 2024 with a remake of Regret of the Times. Which act first released the song?","options":["Seo Taiji and Boys","H.O.T.","S.E.S.","Fin.K.L"],"correct":0,"fun_fact":"The remake was released on January 15, 2024, four months before Supernova arrived.","source":"https://en.wikipedia.org/wiki/Aespa"}]'::jsonb, '2026-11-04'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Supernova_(Aespa_song) ; https://en.wikipedia.org/wiki/Armageddon_(Aespa_album) ; https://en.wikipedia.org/wiki/Armageddon_(Aespa_song) ; https://en.wikipedia.org/wiki/Whiplash_(EP) ; https://en.wikipedia.org/wiki/Whiplash_(Aespa_song) ; https://en.wikipedia.org/wiki/Aespa ; https://en.wikipedia.org/wiki/2024_Melon_Music_Awards ; https://en.wikipedia.org/wiki/2024_MAMA_Awards ; https://en.wikipedia.org/wiki/List_of_Circle_Digital_Chart_number_ones_of_2024 ; https://www.koreatimes.co.kr/entertainment/k-pop/20241201/aespas-meteoric-rise-continues-with-7-melon-awards ; https://koreajoongangdaily.joins.com/news/2024-11-24/entertainment/kpop/Wow-Fantastic-Baby-2024-MAMA-Awards-end-with-a-Big-Bang/2184738 ; https://koreajoongangdaily.joins.com/news/2025-03-24/entertainment/kpop/Girl-group-aespa-to-release-English-version-of-Whiplash/2268760 ; https://koreajoongangdaily.joins.com/news/2024-04-22/entertainment/kpop/aespa-to-release-first-fulllength-album-Armageddon-in-May/2030527 ; https://en.wikipedia.org/wiki/Perfect_all-kill ; https://en.wikipedia.org/wiki/Synk:_Parallel_Line_(single_album) ; https://en.wikipedia.org/wiki/I-dle. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Solo Artists True or False', 'Ten true or false statements about K-pop soloists, from BoA and Rain to IU, Taeyeon, Jennie, Jisoo, Baekhyun and Jungkook.', null, 'true_false', 'hard', 'true_false', '[{"question":"IU made her debut in 2008 with the EP Lost and Found.","correct":true,"fun_fact":"Her agency LOEN came up with the stage name IU, meant to express I and You becoming one through music.","source":"https://en.wikipedia.org/wiki/IU_(entertainer)"},{"question":"Rain launched his solo career in 2002 under SM Entertainment.","correct":false,"fun_fact":"He debuted solo under J. Y. Park''s JYP Entertainment, releasing the album Bad Guy on May 13, 2002.","source":"https://en.wikipedia.org/wiki/Rain_(entertainer)"},{"question":"BoA''s Listen to My Heart was the first album by a Korean artist to top the Oricon Albums Chart.","correct":true,"fun_fact":"Released in Japan in March 2002, it was also the first record by a Korean artist certified million by the RIAJ for one million shipments.","source":"https://en.wikipedia.org/wiki/Listen_to_My_Heart_(BoA_album)"},{"question":"Taeyeon''s debut studio album, released in 2017, was titled Purpose.","correct":false,"fun_fact":"Her first studio album was My Voice (2017). Purpose followed on October 28, 2019, as her second, with the single Spark.","source":"https://en.wikipedia.org/wiki/Taeyeon"},{"question":"Jennie''s debut solo studio album, Ruby, was released in 2025 by Odd Atelier and Columbia Records.","correct":true,"fun_fact":"The 15-track album features guests such as Dua Lipa, Doechii, Childish Gambino, Kali Uchis, Dominic Fike and FKJ.","source":"https://en.wikipedia.org/wiki/Ruby_(Jennie_album)"},{"question":"Sunmi released her 2017 hit Gashina while still signed to JYP Entertainment.","correct":false,"fun_fact":"She had moved to MakeUs Entertainment that year, and Gashina was a collaboration with The Black Label, led by producer Teddy Park.","source":"https://www.koreatimes.co.kr/entertainment/k-pop/20170828/ioi-girls-return-in-different-bands"},{"question":"Jisoo''s 2023 solo debut single, Flower, was released through SM Entertainment.","correct":false,"fun_fact":"It arrived on March 31, 2023, via YG Entertainment and Interscope, leading her first single album, Me.","source":"https://en.wikipedia.org/wiki/Flower_(Jisoo_song)"},{"question":"Chung Ha finished fourth on Produce 101 and became a member of the project group I.O.I.","correct":true,"fun_fact":"After I.O.I''s run ended, she debuted as a soloist in 2017 with the EP Hands on Me.","source":"https://en.wikipedia.org/wiki/Chung_Ha"},{"question":"Jungkook''s 2023 single Seven featured the rapper Cardi B.","correct":false,"fun_fact":"Seven featured Latto and debuted at No. 1 on the Billboard Hot 100: Jungkook''s first solo chart-topper and Latto''s first ever.","source":"https://www.billboard.com/music/chart-beat/jung-kook-latto-seven-number-one-debut-hot-100-jason-aldean-1235377400/"},{"question":"EXO''s Baekhyun made his solo debut in 2019 with the EP City Lights.","correct":true,"fun_fact":"SM Entertainment released the six-track EP on July 10, 2019, with UN Village as its lead single.","source":"https://en.wikipedia.org/wiki/City_Lights_(EP)"}]'::jsonb, '2026-11-05'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/IU_(entertainer) ; https://www.koreaherald.com/article/2561258 ; https://en.wikipedia.org/wiki/Rain_(entertainer) ; https://www.koreatimes.co.kr/entertainment/k-pop/20241115/jyps-founder-thrives-after-30-years-at-helm-of-k-pop-powerhouse ; https://en.wikipedia.org/wiki/BoA ; https://en.wikipedia.org/wiki/Listen_to_My_Heart_(BoA_album) ; https://en.wikipedia.org/wiki/Taeyeon ; https://en.wikipedia.org/wiki/Jennie_(singer) ; https://en.wikipedia.org/wiki/Ruby_(Jennie_album) ; https://www.billboard.com/music/pop/blackpink-jennie-announces-debut-solo-album-ruby-1235880419/ ; https://en.wikipedia.org/wiki/Sunmi ; https://www.koreatimes.co.kr/entertainment/k-pop/20170828/ioi-girls-return-in-different-bands ; https://www.koreaherald.com/article/1264697 ; https://en.wikipedia.org/wiki/Chung_Ha ; https://www.koreaherald.com/article/1352231 ; https://en.wikipedia.org/wiki/Seven_(Jung_Kook_song) ; https://www.billboard.com/music/chart-beat/jung-kook-latto-seven-number-one-debut-hot-100-jason-aldean-1235377400/ ; https://en.wikipedia.org/wiki/Purpose_(Taeyeon_album) ; https://en.wikipedia.org/wiki/Jisoo ; https://en.wikipedia.org/wiki/Flower_(Jisoo_song) ; https://koreaherald.com/view.php?ud=20230331000435 ; https://en.wikipedia.org/wiki/Baekhyun ; https://en.wikipedia.org/wiki/City_Lights_(EP) ; https://www.koreatimes.co.kr/www/art/2024/04/398_271644.html. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('TWICE: Cheer Up to Fancy Quiz', 'From Cheer Up to Fancy: test what you remember about TWICE''s 2016 to 2019 singles, their music videos and the agency behind them.', 4, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which agency launched TWICE in 2015?","options":["SM Entertainment","YG Entertainment","JYP Entertainment","Big Hit Entertainment"],"correct":2,"fun_fact":"Founder J. Y. Park chose the name TWICE: the group would touch hearts once through the ears and again through the eyes.","source":"https://en.wikipedia.org/wiki/Twice"},{"question":"In the Cheer Up music video, Sana dresses as which famous anime heroine?","options":["Sailor Moon","Sakura Kinomoto","Nausicaa","Asuka Langley"],"correct":0,"fun_fact":"Every member plays a film or TV character, such as Tzuyu as Holly Golightly from Breakfast at Tiffany''s.","source":"https://en.wikipedia.org/wiki/Cheer_Up_(song)"},{"question":"Which 2016 TWICE video shows the members in Halloween costumes such as Tinker Bell and Pinocchio?","options":["Heart Shaker","TT","Likey","Fancy"],"correct":1,"fun_fact":"Chaeyoung appears as Ariel from The Little Mermaid, and the video closes with a To be continued message.","source":"https://en.wikipedia.org/wiki/TT_(song)"},{"question":"Which 2017 TWICE video shows a slumber party, a snowball fight and a short cameo by J. Y. Park?","options":["Signal","Heart Shaker","Likey","Knock Knock"],"correct":3,"fun_fact":"Released on February 20, 2017, it led the special album Twicecoaster: Lane 2 and ends with the same scene as the TT video.","source":"https://en.wikipedia.org/wiki/Knock_Knock_(Twice_song)"},{"question":"In the Signal music video, the superpowered members meet what kind of visitor?","options":["A zombie","A vampire","A robot","A green-headed alien"],"correct":3,"fun_fact":"Each member has a power, such as Momo''s super speed, and by the end of the video the members turn into aliens too.","source":"https://en.wikipedia.org/wiki/Signal_(Twice_song)"},{"question":"The Likey music video was filmed entirely in which city?","options":["Los Angeles","Sydney","Vancouver","London"],"correct":2,"fun_fact":"Likey was the lead single of TWICE''s first studio album, Twicetagram, and leader Jihyo shot some of the footage herself.","source":"https://en.wikipedia.org/wiki/Likey"},{"question":"Which 2018 single''s video has the members recreating scenes from films like Ghost and La La Land?","options":["What Is Love?","Yes or Yes","Heart Shaker","Dance the Night Away"],"correct":0,"fun_fact":"The song earned TWICE their third Song of the Year award in a row at the 2018 Mnet Asian Music Awards.","source":"https://en.wikipedia.org/wiki/What_Is_Love%3F_(Twice_song)"},{"question":"The Dance the Night Away video shows TWICE as castaways on a beach. Where was it filmed?","options":["Jeju Island","Okinawa","Bali","Hawaii"],"correct":1,"fun_fact":"Released on July 9, 2018, it was the lead single of Summer Nights, a reissue of their fifth EP.","source":"https://en.wikipedia.org/wiki/Dance_the_Night_Away_(Twice_song)"},{"question":"In the Yes or Yes music video, which object do the members use to have their fortunes told?","options":["A crystal ball","Tarot cards","A fortune cookie","A magic mirror"],"correct":0,"fun_fact":"It hit 100 million YouTube views on December 14, 2018, making ten TWICE music videos in a row to reach that mark.","source":"https://en.wikipedia.org/wiki/Yes_or_Yes_(song)"},{"question":"Which April 2019 single showed a more mature TWICE, with bold CGI backdrops in its video?","options":["Yes or Yes","Knock Knock","Heart Shaker","Fancy"],"correct":3,"fun_fact":"Written by Black Eyed Pilseung and Jeon Goon, the retro electropop track led the group''s seventh EP, Fancy You.","source":"https://en.wikipedia.org/wiki/Fancy_(Twice_song)"}]'::jsonb, '2026-11-06'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Twice ; https://twice.jype.com/profile ; https://www.billboard.com/music/music-news/twice-k-pop-ten-facts-girl-group-7557591/ ; https://www.koreatimes.co.kr/entertainment/k-pop/20260810/twices-jeongyeon-leaves-jyp-to-pursue-acting-career ; https://en.wikipedia.org/wiki/Cheer_Up_(song) ; https://en.wikipedia.org/wiki/TT_(song) ; https://en.wikipedia.org/wiki/Signal_(Twice_song) ; https://en.wikipedia.org/wiki/Likey ; https://en.wikipedia.org/wiki/What_Is_Love%3F_(Twice_song) ; https://en.wikipedia.org/wiki/Dance_the_Night_Away_(Twice_song) ; https://en.wikipedia.org/wiki/Fancy_(Twice_song) ; https://en.wikipedia.org/wiki/Knock_Knock_(Twice_song) ; https://en.wikipedia.org/wiki/Yes_or_Yes_(song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Grand Prize Winners', 'Who took the daesang? Test your memory of Artist and Album of the Year winners at the MAMA, Melon and Golden Disc Awards.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"Which act won the very first MAMA Artist of the Year award, presented in 2006?","options":["Super Junior","BIGBANG","TVXQ","Rain"],"correct":2,"fun_fact":"Super Junior took the award the following year, and BIGBANG won it in 2008.","source":"https://en.wikipedia.org/wiki/MAMA_Award_for_Artist_of_the_Year"},{"question":"Through the 2025 ceremony, how many times had BTS won the MAMA Artist of the Year daesang?","options":["4","5","6","7"],"correct":3,"fun_fact":"Their wins ran every year from 2016 to 2022, a streak no other act had matched as of 2025.","source":"https://en.wikipedia.org/wiki/MAMA_Award_for_Artist_of_the_Year"},{"question":"Which group won MAMA Album of the Year five years in a row, from 2013 to 2017?","options":["EXO","Super Junior","SHINee","BIGBANG"],"correct":0,"fun_fact":"The run began with XOXO and ended with The War, and BTS then won the next five editions from 2018 to 2022.","source":"https://en.wikipedia.org/wiki/MAMA_Award_for_Album_of_the_Year"},{"question":"Which group won the Melon Music Award for Artist of the Year in both 2011 and 2012?","options":["2NE1","Beast","BIGBANG","SHINee"],"correct":1,"fun_fact":"Girls'' Generation had won the two previous editions, and SHINee took the award in 2013.","source":"https://en.wikipedia.org/wiki/Melon_Music_Award_for_Artist_of_the_Year"},{"question":"Which band won Melon Album of the Year in both 2012 and 2013?","options":["CNBLUE","Hyukoh","Busker Busker","Day6"],"correct":2,"fun_fact":"They won first with Busker Busker 1st Album and again the next year with their second album.","source":"https://en.wikipedia.org/wiki/Melon_Music_Award_for_Album_of_the_Year"},{"question":"Which IU album was named Melon Album of the Year in 2017?","options":["Lilac","Palette","Love Poem","Chat-Shire"],"correct":1,"fun_fact":"She won the same grand prize again in 2021, that time with Lilac.","source":"https://en.wikipedia.org/wiki/Melon_Music_Award_for_Album_of_the_Year"},{"question":"At the 2022 Melon Music Awards, which singer took both Artist of the Year and Album of the Year?","options":["Lim Young-woong","IU","Zico","Psy"],"correct":0,"fun_fact":"BTS received Record of the Year that night, and IVE won Song of the Year, the group''s first ever daesang.","source":"https://en.wikipedia.org/wiki/2022_Melon_Music_Awards"},{"question":"Which TVXQ album won Album of the Year at the 2008 Mnet KM Music Festival?","options":["Catch Me","Rising Sun","Keep Your Head Down","Mirotic"],"correct":3,"fun_fact":"Released in September 2008 as their fourth Korean studio album, it also won the Disk Daesang at the 23rd Golden Disc Awards.","source":"https://en.wikipedia.org/wiki/Mirotic_(album)"},{"question":"Who won the Golden Disc Awards'' new Artist Daesang, first given at the 40th ceremony in January 2026?","options":["Rosé","G-Dragon","IU","Jennie"],"correct":3,"fun_fact":"The ceremony took place at the Taipei Dome, and Stray Kids won that year''s Album Daesang with Karma.","source":"https://en.wikipedia.org/wiki/40th_Golden_Disc_Awards"},{"question":"At the 2025 Melon Music Awards, who swept Song, Artist and Album of the Year?","options":["aespa","Jennie","G-Dragon","Rosé"],"correct":2,"fun_fact":"He won seven awards at Gocheok Sky Dome that night, while Record of the Year went to Jennie.","source":"https://en.wikipedia.org/wiki/2025_Melon_Music_Awards"}]'::jsonb, '2026-11-07'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/MAMA_Award_for_Artist_of_the_Year ; https://en.wikipedia.org/wiki/MAMA_Award_for_Album_of_the_Year ; https://en.wikipedia.org/wiki/Melon_Music_Award_for_Artist_of_the_Year ; https://en.wikipedia.org/wiki/Melon_Music_Award_for_Album_of_the_Year ; https://en.wikipedia.org/wiki/2022_Melon_Music_Awards ; https://en.wikipedia.org/wiki/Mirotic_(album) ; https://en.wikipedia.org/wiki/Golden_Disc_Awards ; https://en.wikipedia.org/wiki/40th_Golden_Disc_Awards ; https://en.wikipedia.org/wiki/2025_Melon_Music_Awards ; https://en.wikipedia.org/wiki/2025_MAMA_Awards. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Virtual Idols', 'PLAVE, K/DA, MAVE: and naevis: ten questions on the virtual idols and digital singers who have made their mark on K-pop.', null, 'multiple_choice', 'medium', 'fun', '[{"question":"Which agency is behind the virtual boy band PLAVE?","options":["Pulse9","Vlast","Metaverse Entertainment","Riot Games"],"correct":1,"fun_fact":"In April 2024, Vlast''s CEO said HYBE and YG Plus had invested in the company to help PLAVE expand overseas.","source":"https://en.wikipedia.org/wiki/Plave"},{"question":"Which single album marked PLAVE''s formal debut in March 2023?","options":["Caligo Pt.1","Pandora''s Box","Asterum","All Out"],"correct":2,"fun_fact":"PLAVE''s name mixes the English word play with rêve, French for dream.","source":"https://en.wikipedia.org/wiki/Plave"},{"question":"In 2024, PLAVE became the first virtual idol group to win a Korean music show. With which song?","options":["Way 4 Luv","Dash","Pop/Stars","Pandora"],"correct":0,"fun_fact":"The song took first place on both Show Champion and Show! Music Core.","source":"https://en.wikipedia.org/wiki/Plave"},{"question":"Which HYBE-run fan platform did PLAVE become the first virtual group to join?","options":["Lysn","Berriz","Universe","Weverse"],"correct":3,"fun_fact":"They announced the move during a livestream on December 12, 2023, and opened their official fan club membership there in early 2024.","source":"https://en.wikipedia.org/wiki/Plave"},{"question":"The members of the virtual girl group K/DA are versions of characters from which video game?","options":["Overwatch","Valorant","League of Legends","Fortnite"],"correct":2,"fun_fact":"Riot Games unveiled the group in 2018 with a mixed-reality performance at the World Championship opening ceremony in Incheon.","source":"https://www.billboard.com/pro/league-of-legends-virtual-k-pop-girl-group-kda-music-esports/"},{"question":"Which two members of (G)I-DLE, now called i-dle, voice Ahri and Akali in K/DA?","options":["Yuqi and Minnie","Shuhua and Yuqi","Minnie and Shuhua","Miyeon and Soyeon"],"correct":3,"fun_fact":"The other two characters are voiced by American singers: Madison Beer as Evelynn and Jaira Burns as Kai''Sa.","source":"https://www.billboard.com/pro/league-of-legends-virtual-k-pop-girl-group-kda-music-esports/"},{"question":"What was K/DA''s debut single, released on November 3, 2018?","options":["Pop/Stars","More","The Baddest","Drum Go Dum"],"correct":0,"fun_fact":"Within days it reached No. 1 on Billboard''s World Digital Song Sales chart and on the US iTunes K-pop chart.","source":"https://www.koreaherald.com/view.php?ud=20181114000662"},{"question":"The virtual girl group MAVE: was launched by an affiliate of which game company?","options":["Nexon","Netmarble","NCSoft","Krafton"],"correct":1,"fun_fact":"Its four virtual members, SIU:, ZENA:, TYRA: and MARTY:, debuted on January 25, 2023, with the album Pandora''s Box.","source":"https://www.koreatimes.co.kr/www/tech/2023/01/133_344172.html"},{"question":"Which agency debuted naevis, its first AI-generated singer, in 2024?","options":["JYP Entertainment","YG Entertainment","SM Entertainment","HYBE"],"correct":2,"fun_fact":"She first appeared in aespa''s fictional universe, where she helps the members travel to the digital world called Kwangya.","source":"https://www.nme.com/news/music/sm-entertainment-debut-first-ai-singer-naevis-3785500"},{"question":"What was the title of naevis''s debut single, released in September 2024?","options":["Done","Pandora","I''m Real","Dash"],"correct":0,"fun_fact":"Years before going solo, she showed up in the video for aespa''s Black Mamba, released in November 2020.","source":"https://www.koreaherald.com/article/10420599"}]'::jsonb, '2026-11-08'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Plave ; https://www.koreaherald.com/article/10489798 ; https://www.billboard.com/pro/league-of-legends-virtual-k-pop-girl-group-kda-music-esports/ ; https://www.koreaherald.com/view.php?ud=20181114000662 ; https://en.wikipedia.org/wiki/K/DA ; https://www.koreatimes.co.kr/www/tech/2023/01/133_344172.html ; https://en.wikipedia.org/wiki/Mave: ; https://www.nme.com/news/music/sm-entertainment-debut-first-ai-singer-naevis-3785500 ; https://www.koreaherald.com/article/10420599 ; https://en.wikipedia.org/wiki/Naevis ; https://koreaherald.com/view.php?ud=20240303050195 ; https://en.wikipedia.org/wiki/Weverse ; https://en.wikipedia.org/wiki/Lysn ; https://www.koreaherald.com/article/10449874 ; https://www.koreaherald.com/article/2548585 ; https://en.wikipedia.org/wiki/I-dle. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.');
